"OLAYLAR_ARKEOLOJI_D2_ITALYA_AVRUPA:-5499-01-01:0":{"b": ["Linearbandkeramik formative (Transdanubi): Shfaqet LBK formative në Transdanubi", "58c54ad2"], "d": ["Komunitetet e para bujqësore të Evropës Qendrore, shtëpi të gjata, qeramikë me vija; përhapje e shpejtë ('diaspora') në mes të shek. 54.", "99d39808"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0039-01-01:0":{"b": ["Kultura Paracas (nënrajoni Paracas/Ica): mbaron Paracasi i Vonë", "245df0ec"], "d": ["Kultura materiale Paracas në nënrajonet Paracas/Ica, Palpa dhe Nasca të bregdetit jugor të Perusë; përhapje me qendër në veri (Palpa/Ica) drejt jugut.", "c02dd334"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0099-01-01:0":{"b": ["Kaminaljuyu (lugina e Guatemalës): faza Providencia / ngritja e Preklasikut të Vonë: mbaron faza Providencia", "62267db9"], "d": ["Në Kaminaljuyu, fundi i fazës Las Charcas dhe fillimi i fazës Providencia (~350 p.e.s.) përkojnë me kufirin Preklasik i Mesëm-i Vonë; Providencia ~350-100/75 p.e.s., pastaj në fazat Verbena-Arenal (Preklasiku Terminal) shpërthim i popullsisë dhe ndërtimit. Kronologjia e Inomata dhe të tjerë 2014 e 2020 i zhvendosi datat tradicionale të Shook & Popenoe de Hatch (1999) 300-400 vjet më vonë.", "5785c9d9"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0141-01-01:0":{"b": ["Tradita Topará (Jahuay, Chincha): Topará: fillon banimi në Jahuay", "a334d215"], "d": ["Fillimi i modeluar i Jahuayt, vendbanimi Topará që pranohet si më i vjetri; pas mbylljes rituale të qendrave monumentale Paracas.", "57da5de8"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0340-01-01:0":{"b": ["Kultura e Varreve me Pllaka (Slab Grave), Mongoli: mbarojnë varrimet Slab Grave (mesorja)", "bfd3a66c"], "d": ["Kulturë e Epokës së Hershme të Hekurit, e njohur nga varret katërkëndore me pllaka guri; del nga tradita e varreve me forma dhe zë vendin e kompleksit Gurët e Drerit-Hirigsuur (gjenetikisht ndërrim popullsie). Gurët e drerit dhe gurët e hirigsuurëve janë ripërdorur në ndërtimin e varreve me pllaka.", "70bca5a7"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0349-01-01:0":{"b": ["Kaminaljuyu (lugina e Guatemalës): faza Providencia / ngritja e Preklasikut të Vonë: Kaminaljuyú: faza Providencia", "fc241708"], "d": ["Në Kaminaljuyu, fundi i fazës Las Charcas dhe fillimi i fazës Providencia (~350 p.e.s.) përkojnë me kufirin Preklasik i Mesëm-i Vonë; Providencia ~350-100/75 p.e.s., pastaj në fazat Verbena-Arenal (Preklasiku Terminal) shpërthim i popullsisë dhe ndërtimit. Kronologjia e Inomata dhe të tjerë 2014 e 2020 i zhvendosi datat tradicionale të Shook & Popenoe de Hatch (1999) 300-400 vjet më vonë.", "5785c9d9"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0499-01-01:0":{"b": ["San Jose Mogote: braktisja e vendbanimit fshatar dhe e qendrës ceremoniale pas Rosarios: fundi i fazës Rosario: shumica e popullsisë shkon në Monte Albán", "544d781b"], "d": ["San Jose Mogote, në luginë (Oaxaca, dega Etla), në fazën Tierras Largas (1500-1150 p.e.s.) ishte fshat me të paktën 7 ha; në fazën Rosario ishte qendra e kryesisë së një grupi prej 18-23 fshatrash. Në fund të Rosarios rreth 95% e popullsisë shkoi për t'iu bashkuar themelimit të Monte Albanit; qendra 40 ha në Mound 1 mbeti e braktisur deri në fillim të Monte Alban II (100 p.e.s.).", "8b8229e9"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0599-01-01:0":{"b": ["La Blanca (San Marcos, Guatemala e Paqësorit): qendër rajonale e Preklasikut të Mesëm, Mound 1: rënia e La Blancas", "502fae46"], "d": ["La Blanca, pas shembjes së qendrës politike të Preklasikut të Hershëm Ojo de Agua (Chiapas), u bë në Preklasikun e Mesëm (faza Conchas, ~900-600 p.e.s.) qendër rajonale për rreth 300 vjet; në kulm, me mbi 200 ha dhe Mound 1 25 m të lartë (një nga tempujt-piramidë më të vjetër të Mezoamerikës). Rreth 600 p.e.s. ra për arsye të panjohur.", "2085e434"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0742-01-01:0":{"b": ["Nukuleka (zbarkimi i parë Lapita), Tongatapu: mbaron faza Lapita e Tongatapusë", "bd1edd93"], "d": ["Nukuleka është vendi i zbarkimit të parë Lapita në Tonga dhe Polinezi (qeramika Lapita e tipit perëndimor vetëm këtu). Faza Lapita në Tongatapu zgjat pak (~129-158 vjet) dhe kalon në Qeramikën e Thjeshtë Polineziane.", "5ee89d7b"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0749-01-01:0":{"b": ["Izapa (Chiapas): kryeqytet mbretërie i Formativit të Mesëm dhe sipërfaqja e parë me argjilë të bardhë: Izapa: banimi i Formativit të Mesëm", "d72b1e47"], "d": ["Izapa u themelua në gjysmën e dytë të Formativit të Mesëm (750-300 cal p.e.s.) si kryeqytet mbretërie. Në fazën Escalon (750-500 cal BC) nën Mound 30a u bë sipërfaqja me argjilë të bardhë; në fazën Guillen (300-100 cal BC, Formativi i Vonë) vazhdon ndërtimi dhe ngritja e stelave në Mound 62; grupi E u ngrit në fund të Formativit të Mesëm dhe u zgjerua në Guillen.", "6b7f8e16"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-0789-01-01:0":{"b": ["Kultura Paracas (nënrajoni Paracas/Ica): kultura Paracas (Ica) arrin nivelin e ngulitur", "cd5d9c2a"], "d": ["Kultura materiale Paracas në nënrajonet Paracas/Ica, Palpa dhe Nasca të bregdetit jugor të Perusë; përhapje me qendër në veri (Palpa/Ica) drejt jugut.", "c02dd334"]}
